// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {GameItems} from "../src/GameItems.sol";

contract InvMutTest is Test {
    GameItems c;
    function setUp() public { c = new GameItems(address(this), address(this)); }
    function testRegression_property() public {
        bool ok = false;
        try c.balanceOf(address(0), 0) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(ok == false, "balanceOf on zero address should revert in the original");
    }
}
